"use client";
import { useEffect, useState } from "react";
import type { ActionResult } from "@/lib/errors";
export function SavedStatus({ result }: { result?: ActionResult }) {
  const [shown, setShown] = useState<ActionResult>();
  useEffect(() => {
    if (!result?.ok) return;
    const show = setTimeout(() => setShown(result), 0);
    const hide = setTimeout(() => setShown(undefined), 1800);
    return () => {
      clearTimeout(show);
      clearTimeout(hide);
    };
  }, [result]);
  return (
    <span
      role="status"
      className="text-[var(--settings-green)] text-[13px] font-semibold"
    >
      {result?.ok && shown === result ? "Saved ✓" : ""}
    </span>
  );
}
